/*
Zales – final aligned installation script

This script creates a clean database named zales.
It preserves the original sales data used for the Power BI report:
Customized = 1814 units
Default    = 1826 units

Physical-table convention: plural names.
SEARCHES has a composite primary key: (Search_IP, Search_DT).
*/


-- ============================================================
-- Part 3 SQL - Zales Jewelry Database - Group 18
-- ============================================================

USE master;
GO

IF DB_ID(N'zales') IS NOT NULL
BEGIN
    ALTER DATABASE [zales] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE [zales];
END;
GO

CREATE DATABASE [zales];
GO

USE [zales];
GO

CREATE TABLE dbo.CUSTOMERS (
    Email        varchar(100) NOT NULL,
    [Password]   varchar(50) NULL,
    Name_Last    varchar(50) NOT NULL,
    Name_First   varchar(50) NOT NULL,
    Phone        varchar(25) NOT NULL,
    CONSTRAINT PK_CUSTOMERS PRIMARY KEY (Email)
);
GO

CREATE TABLE dbo.CREDIT_CARDS (
    CCNumber     char(16) NOT NULL,
    Owner_ID     varchar(100) NOT NULL,
    Expiry_Date  char(5) NOT NULL,
    CVV          char(3) NOT NULL,
    CONSTRAINT PK_CREDIT_CARDS PRIMARY KEY (CCNumber),
    CONSTRAINT FK_CREDIT_CARDS_CUSTOMERS
        FOREIGN KEY (Owner_ID) REFERENCES dbo.CUSTOMERS(Email)
);
GO

CREATE TABLE dbo.JEWELRY (
    Jewelry      int NOT NULL,
    Product_Name varchar(100) NOT NULL,
    Category     varchar(30) NOT NULL,
    CONSTRAINT PK_JEWELRY PRIMARY KEY (Jewelry)
);
GO

CREATE TABLE dbo.JEWELRY_VARIANTS (
    Jewelry_Variant int NOT NULL,
    Jewelry         int NOT NULL,
    Variant_Type    varchar(20) NOT NULL,
    [Size]          varchar(30) NOT NULL,
    Color           varchar(30) NOT NULL,
    CONSTRAINT PK_JEWELRY_VARIANTS PRIMARY KEY (Jewelry_Variant),
    CONSTRAINT FK_JEWELRY_VARIANTS_JEWELRY
        FOREIGN KEY (Jewelry) REFERENCES dbo.JEWELRY(Jewelry),
    CONSTRAINT CK_JEWELRY_VARIANTS_TYPE
        CHECK (Variant_Type IN ('Customized', 'Default'))
);
GO

CREATE TABLE dbo.COMPONENTS (
    Component      int NOT NULL,
    Material       varchar(50) NOT NULL,
    Price_Addition decimal(10,2) NOT NULL,
    CONSTRAINT PK_COMPONENTS PRIMARY KEY (Component),
    CONSTRAINT CK_COMPONENTS_PRICE CHECK (Price_Addition >= 0)
);
GO

CREATE TABLE dbo.ORDERS_TABLE (
    Order_ID          int NOT NULL,
    [Date]            date NOT NULL,
    Address_State     varchar(50) NOT NULL,
    Address_City      varchar(100) NOT NULL,
    Address_Street    varchar(100) NOT NULL,
    Address_HouseNum  varchar(10) NOT NULL,
    Address_Zip       char(5) NOT NULL,
    Delivery_Method   varchar(30) NOT NULL,
    Email             varchar(100) NOT NULL,
    CCNumber          char(16) NOT NULL,
    Total_Order_Value decimal(12,2) NULL,
    Packaging_Type    varchar(50) NULL,
    CONSTRAINT PK_ORDERS_TABLE PRIMARY KEY (Order_ID),
    CONSTRAINT FK_ORDERS_TABLE_CUSTOMERS
        FOREIGN KEY (Email) REFERENCES dbo.CUSTOMERS(Email),
    CONSTRAINT FK_ORDERS_TABLE_CREDIT_CARDS
        FOREIGN KEY (CCNumber) REFERENCES dbo.CREDIT_CARDS(CCNumber)
);
GO

CREATE TABLE dbo.BUILDS_FROM (
    Jewelry_Variant int NOT NULL,
    Component       int NOT NULL,
    CONSTRAINT PK_BUILDS_FROM PRIMARY KEY (Jewelry_Variant, Component),
    CONSTRAINT FK_BUILDS_FROM_VARIANTS
        FOREIGN KEY (Jewelry_Variant) REFERENCES dbo.JEWELRY_VARIANTS(Jewelry_Variant),
    CONSTRAINT FK_BUILDS_FROM_COMPONENTS
        FOREIGN KEY (Component) REFERENCES dbo.COMPONENTS(Component)
);
GO

CREATE TABLE dbo.INCLUDES (
    Order_ID         int NOT NULL,
    Jewelry_Variant  int NOT NULL,
    Quantity         int NOT NULL,
    CONSTRAINT PK_INCLUDES PRIMARY KEY (Order_ID, Jewelry_Variant),
    CONSTRAINT FK_INCLUDES_ORDERS
        FOREIGN KEY (Order_ID) REFERENCES dbo.ORDERS_TABLE(Order_ID),
    CONSTRAINT FK_INCLUDES_VARIANTS
        FOREIGN KEY (Jewelry_Variant) REFERENCES dbo.JEWELRY_VARIANTS(Jewelry_Variant),
    CONSTRAINT CK_INCLUDES_QUANTITY CHECK (Quantity > 0)
);
GO

CREATE TABLE dbo.SEARCHES (
    Search_IP      varchar(45) NOT NULL,
    Search_DT      datetime2(0) NOT NULL,
    Search_Text    varchar(100) NOT NULL,
    Search_Filter  varchar(30) NOT NULL,
    Sort_Method    varchar(50) NOT NULL,
    Email          varchar(100) NOT NULL,
    CONSTRAINT PK_SEARCHES PRIMARY KEY (Search_IP, Search_DT),
    CONSTRAINT FK_SEARCHES_CUSTOMERS
        FOREIGN KEY (Email) REFERENCES dbo.CUSTOMERS(Email)
);
GO

CREATE TABLE dbo.SEARCH_RETURNS (
    Search_IP   varchar(45) NOT NULL,
    Search_DT   datetime2(0) NOT NULL,
    Jewelry     int NOT NULL,
    Result_Rank int NOT NULL,
    Clicked     bit NOT NULL,
    CONSTRAINT PK_SEARCH_RETURNS PRIMARY KEY (Search_IP, Search_DT, Jewelry),
    CONSTRAINT FK_SEARCH_RETURNS_SEARCHES
        FOREIGN KEY (Search_IP, Search_DT)
        REFERENCES dbo.SEARCHES(Search_IP, Search_DT),
    CONSTRAINT FK_SEARCH_RETURNS_JEWELRY
        FOREIGN KEY (Jewelry) REFERENCES dbo.JEWELRY(Jewelry),
    CONSTRAINT CK_SEARCH_RETURNS_RANK CHECK (Result_Rank BETWEEN 1 AND 20)
);
GO

