/* Set the initial stored value for all existing orders */
UPDATE O
SET Total_Order_Value = X.Order_Total
FROM dbo.ORDERS_TABLE AS O
JOIN (
    SELECT
        I.Order_ID,
        SUM(I.Quantity * C.Price_Addition) AS Order_Total
    FROM dbo.INCLUDES AS I
    JOIN dbo.BUILDS_FROM AS BF
        ON I.Jewelry_Variant = BF.Jewelry_Variant
    JOIN dbo.COMPONENTS AS C
        ON BF.Component = C.Component
    GROUP BY I.Order_ID
) AS X
    ON O.Order_ID = X.Order_ID;
GO

CREATE VIEW dbo.V_ORDER_ANALYSIS
AS
SELECT
    O.Order_ID,
    O.[Date],
    O.Address_State,
    O.Delivery_Method,
    C.Email,
    C.Name_First,
    C.Name_Last,
    SUM(I.Quantity) AS Total_Physical_Items,
    SUM(I.Quantity * CO.Price_Addition) AS Total_Order_Revenue
FROM dbo.ORDERS_TABLE AS O
JOIN dbo.CUSTOMERS AS C
    ON O.Email = C.Email
JOIN dbo.INCLUDES AS I
    ON O.Order_ID = I.Order_ID
JOIN dbo.BUILDS_FROM AS BF
    ON I.Jewelry_Variant = BF.Jewelry_Variant
JOIN dbo.COMPONENTS AS CO
    ON BF.Component = CO.Component
GROUP BY
    O.Order_ID,
    O.[Date],
    O.Address_State,
    O.Delivery_Method,
    C.Email,
    C.Name_First,
    C.Name_Last;
GO

CREATE FUNCTION dbo.GetStateSalesSummary (@State VARCHAR(50))
RETURNS TABLE
AS
RETURN (
    SELECT
        C.Email,
        C.Name_First,
        C.Name_Last,
        C.Phone,
        SUM(I.Quantity * CP.Price_Addition) AS Total_Spent,
        COUNT(DISTINCT O.Order_ID) AS Order_Count,
        MAX(O.[Date]) AS Last_Order
    FROM dbo.CUSTOMERS AS C
    JOIN dbo.ORDERS_TABLE AS O
        ON C.Email = O.Email
    JOIN dbo.INCLUDES AS I
        ON O.Order_ID = I.Order_ID
    JOIN dbo.BUILDS_FROM AS BF
        ON I.Jewelry_Variant = BF.Jewelry_Variant
    JOIN dbo.COMPONENTS AS CP
        ON BF.Component = CP.Component
    WHERE O.Address_State = @State
    GROUP BY C.Email, C.Name_First, C.Name_Last, C.Phone
);
GO

CREATE TRIGGER dbo.trg_UpdateOrderValue
ON dbo.INCLUDES
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    IF @@ROWCOUNT = 0 RETURN;

    ;WITH AffectedOrders AS (
        SELECT Order_ID FROM inserted
        UNION
        SELECT Order_ID FROM deleted
    )
    UPDATE O
    SET Total_Order_Value = ISNULL((
        SELECT SUM(I.Quantity * C.Price_Addition)
        FROM dbo.INCLUDES AS I
        JOIN dbo.BUILDS_FROM AS BF
            ON I.Jewelry_Variant = BF.Jewelry_Variant
        JOIN dbo.COMPONENTS AS C
            ON BF.Component = C.Component
        WHERE I.Order_ID = O.Order_ID
    ), 0)
    FROM dbo.ORDERS_TABLE AS O
    JOIN AffectedOrders AS A
        ON O.Order_ID = A.Order_ID;
END;
GO

CREATE PROCEDURE dbo.sp_SetOrderPackaging
    @OrderID INT
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE dbo.ORDERS_TABLE
    SET Packaging_Type = (
        SELECT CASE
            WHEN Total_Order_Revenue >= 2000 THEN 'Premium Velvet Box'
            ELSE 'Standard Box'
        END
        FROM dbo.V_ORDER_ANALYSIS
        WHERE Order_ID = @OrderID
    )
    WHERE Order_ID = @OrderID;

    SELECT Order_ID, Packaging_Type
    FROM dbo.ORDERS_TABLE
    WHERE Order_ID = @OrderID;
END;
GO

/* Final validation: expected report totals */
SELECT
    JV.Variant_Type,
    SUM(I.Quantity) AS Units_Sold
FROM dbo.INCLUDES AS I
JOIN dbo.JEWELRY_VARIANTS AS JV
    ON I.Jewelry_Variant = JV.Jewelry_Variant
GROUP BY JV.Variant_Type
ORDER BY JV.Variant_Type;
GO

/* Final validation: SEARCHES composite primary key */
SELECT
    c.name AS Primary_Key_Column,
    ic.key_ordinal AS Key_Order
FROM sys.indexes AS i
JOIN sys.index_columns AS ic
    ON i.object_id = ic.object_id
   AND i.index_id = ic.index_id
JOIN sys.columns AS c
    ON ic.object_id = c.object_id
   AND ic.column_id = c.column_id
WHERE i.is_primary_key = 1
  AND OBJECT_NAME(i.object_id) = 'SEARCHES'
ORDER BY ic.key_ordinal;
GO

